// ══════════════════════════════════════════════════════════════════
//  THE LIBRARY INDEX, AS DATA
// ══════════════════════════════════════════════════════════════════
// `index.json` is the one file the app downloads before a reader has asked for
// anything. It lists every entry with what the listing needs — title, type,
// badges, picture paths, the content hash — and it is generated by the
// library's CI, never written by hand. See scripts/library/build.mjs.
//
// Everything a badge claims was computed by that CI from the machine itself;
// nothing in here is taken from the author's say-so except the words they
// wrote about it. That is the library's whole distinction, so this module never
// invents a fact: an entry the CI could not analyse carries no badge rather
// than a guess.
//
// Import-free — the website's browser script and CI both use it.

import { INDEX_FORMAT, INDEX_VERSION, isLibraryId } from './config.js';

/** The machine families, in the model picker's order. Mirrors MachineCategories. */
export const LIBRARY_FAMILIES = [
  { id: 'fa', label: 'Finite automata' },
  { id: 'omega', label: 'ω-automata' },
  { id: 'mem', label: 'Memory automata' },
  { id: 'tm', label: 'Turing machines' },
  { id: 'special', label: 'Transducers' }
];

/** Every badge the CI can award, with what earns it. The order is display order. */
export const BADGES = {
  tested: { label: 'Tests pass', icon: '✓', say: 'Every accept, reject and output example the author declared was checked by running the machine.' },
  deterministic: { label: 'Deterministic', icon: '◆', say: 'No state has two transitions that could fire on the same input.' },
  minimal: { label: 'Minimal', icon: '✂', say: 'No DFA for this language has fewer states.' },
  halts: { label: 'Halts', icon: '■', say: 'Run from a blank tape, the machine stops. The step count is exact.' },
  'never-halts': { label: 'Never halts', icon: '∞', say: 'Proven never to halt from a blank tape, by the method named.' }
};

export const DIFFICULTIES = ['intro', 'intermediate', 'advanced'];

/** The pictures a card can show in turn, and what each is called on screen. */
export const ART_LABELS = { spacetime: 'Run', diagram: 'Diagram', language: 'Language' };
const ART_KIND_SET = new Set(Object.keys(ART_LABELS));

/**
 * What a list can be sorted by, and the two directions each reads in. `dir` is
 * the direction a field starts in — the one a reader means by picking it — and
 * `say` names both in the field's own terms, so the second control reads
 * "Newest first" rather than "Descending". Best match has one direction.
 */
export const SORTS = {
  relevance: { label: 'Best match' },
  added: { label: 'Date added', dir: 'desc', say: { desc: 'Newest first', asc: 'Oldest first' } },
  updated: { label: 'Last updated', dir: 'desc', say: { desc: 'Newest first', asc: 'Oldest first' } },
  title: { label: 'Title', dir: 'asc', say: { asc: 'A → Z', desc: 'Z → A' } },
  states: { label: 'States', dir: 'asc', say: { asc: 'Fewest first', desc: 'Most first' } }
};

// The names the sorts had before they took a direction; links still carry them.
const SORT_ALIASES = { newest: ['updated', 'desc'], smallest: ['states', 'asc'] };

/** A sort as a link or a control names it → `{ key, dir }`, always one SORTS knows. */
export function resolveSort(sort, dir) {
  const [key, implied] = SORT_ALIASES[sort] || [SORTS[sort] ? sort : 'relevance'];
  const s = SORTS[key];
  if (!s.say) return { key, dir: null };
  return { key, dir: s.say[dir] ? dir : (implied || s.dir) };
}

/**
 * An index date as a time, or null. Compared as times, never as strings: git
 * writes each date in its committer's own offset, and "…T09:00+05:30" sorts
 * after "…T05:00Z" as text while being earlier.
 */
export function dateOf(iso) {
  const t = Date.parse(iso || '');
  return Number.isFinite(t) ? t : null;
}

/** Whether an entry was changed after it was listed, rather than only listed. */
export function wasUpdated(e) {
  const a = dateOf(e?.added), u = dateOf(e?.updated);
  return a !== null && u !== null && u > a;
}

// ── Reading one ───────────────────────────────────────────────────

const str = (v, max = 400) => (typeof v === 'string' ? v.slice(0, max) : '');
const num = v => (Number.isFinite(v) ? v : 0);
const arr = v => (Array.isArray(v) ? v : []);

/**
 * A fetched index, checked and filled in. Throws on a document that is not an
 * index at all or is from a newer format; tolerates everything else, the way
 * the workspace readers do — an entry missing an optional field gets its
 * default, and an entry with no usable id is dropped rather than rendered as
 * a card that links nowhere.
 */
export function normalizeIndex(raw) {
  if (!raw || typeof raw !== 'object') throw new Error('The library index is not a JSON object.');
  if (raw.format !== INDEX_FORMAT) throw new Error('This is not an AutomataStudio library index.');
  if (Number.isInteger(raw.version) && raw.version > INDEX_VERSION) {
    throw new Error(`The library index is format ${raw.version}; this build reads ${INDEX_VERSION}. Update the app to browse it.`);
  }
  const entries = arr(raw.entries).map(normalizeEntry).filter(Boolean);
  const ids = new Set(entries.map(e => e.id));
  const collections = arr(raw.collections).map(c => ({
    id: str(c?.id, 120),
    title: str(c?.title, 120) || 'Collection',
    blurb: str(c?.blurb, 1000),
    curator: str(c?.curator, 60),
    entries: arr(c?.entries).filter(id => ids.has(id))
  })).filter(c => isLibraryId(c.id));
  return {
    format: INDEX_FORMAT,
    version: Number.isInteger(raw.version) ? raw.version : INDEX_VERSION,
    generated: str(raw.generated, 40),
    engine: str(raw.engine, 40),
    repo: str(raw.repo, 120),
    commit: /^[0-9a-f]{7,40}$/.test(raw.commit || '') ? raw.commit : '',
    site: str(raw.site, 300),
    submit: /^https?:\/\//.test(raw.submit || '') ? raw.submit : '',
    emulator: raw.emulator === true,
    entries,
    collections,
    featured: arr(raw.featured).filter(id => collections.some(c => c.id === id)),
    // The machine the home pages open on, as the build chose it (pickFrontispiece).
    frontispiece: ids.has(raw.frontispiece) ? raw.frontispiece : null
  };
}

function normalizeEntry(e) {
  if (!e || typeof e !== 'object' || !isLibraryId(e.id)) return null;
  const stats = e.stats && typeof e.stats === 'object' ? e.stats : {};
  const author = e.author && typeof e.author === 'object' ? e.author : {};
  return {
    id: e.id,
    path: str(e.path, 300) || `machines/${e.id}.automaton`,
    title: str(e.title, 120) || e.id.split('/').pop(),
    blurb: str(e.blurb, 2000),
    machine: str(e.machine, 20),
    category: str(e.category, 20),
    tags: arr(e.tags).filter(t => typeof t === 'string').map(t => t.toLowerCase().slice(0, 40)).slice(0, 20),
    author: { login: str(author.login, 40), name: str(author.name, 80) },
    license: str(e.license, 40),
    difficulty: DIFFICULTIES.includes(e.difficulty) ? e.difficulty : '',
    chapter: str(e.chapter, 80),
    added: str(e.added, 40),
    updated: str(e.updated, 40) || str(e.added, 40),
    version: Number.isInteger(e.version) && e.version > 0 ? e.version : 1,
    hash: str(e.hash, 32),
    bytes: num(e.bytes),
    stats: {
      states: num(stats.states), transitions: num(stats.transitions),
      sigma: arr(stats.sigma).map(String).slice(0, 64), tapes: num(stats.tapes) || 1, blocks: num(stats.blocks)
    },
    languageClass: str(e.languageClass, 80),
    standard: /^[0-9LRA-Z_-]{3,2000}$/.test(e.standard || '') ? e.standard : null,
    badges: arr(e.badges).filter(b => b && BADGES[b.id]).map(b => ({ id: b.id, detail: str(b.detail, 200) })),
    behaviour: e.behaviour && typeof e.behaviour === 'object' ? e.behaviour : null,
    fingerprint: str(e.fingerprint, 32) || null,
    machineId: /^[0-9a-f]{16}$/.test(e.machineId || '') ? e.machineId : null,
    taskId: /^[0-9a-f]{16}$/.test(e.taskId || '') ? e.taskId : null,
    dfa: validDfaTable(e.dfa) ? e.dfa : null,
    sketch: validSketch(e.sketch) ? e.sketch : null,
    tests: { accepts: num(e.tests?.accepts), rejects: num(e.tests?.rejects), outputs: num(e.tests?.outputs) },
    art: arr(e.art).filter(a => a && ART_KIND_SET.has(a.kind) && typeof a.path === 'string').map(a => ({ kind: a.kind, path: a.path.slice(0, 300) })),
    forkOf: isLibraryId(e.forkOf) ? e.forkOf : null,
    remixes: arr(e.remixes).filter(isLibraryId),
    collections: arr(e.collections).filter(isLibraryId),
    duplicateOf: isLibraryId(e.duplicateOf) ? e.duplicateOf : null
  };
}

/** A machine's packed shape (js/library/sketch.js packSketch): points and index pairs, nothing else. */
function validSketch(k) {
  if (!k || !Array.isArray(k.n) || !Array.isArray(k.e) || !k.n.length || k.n.length > 60 || k.e.length > 240) return false;
  return k.n.every(p => Array.isArray(p) && p.length === 3 && p.every(Number.isFinite))
    && k.e.every(p => Array.isArray(p) && p.length === 2 && p.every(i => Number.isInteger(i) && i >= 0 && i < k.n.length));
}

function validDfaTable(d) {
  if (!d || typeof d !== 'object') return false;
  const k = Array.isArray(d.sigma) ? d.sigma.length : -1;
  return k >= 0 && Number.isInteger(d.n) && d.n > 0 && Number.isInteger(d.start)
    && Array.isArray(d.acc) && Array.isArray(d.delta) && d.delta.length === d.n * k;
}

export function entryById(index, id) {
  return index?.entries.find(e => e.id === id) || null;
}

// ── Asking it questions ───────────────────────────────────────────

/**
 * The search box's text → a structured query. Plain words match the text of an
 * entry; `key:value` terms filter:
 *
 *   type:DFA  family:tm  tag:parity  by:login  badge:minimal
 *   states:<10  states:>=3  accepts:abba  rejects:ab  level:intro
 *   code:<machine id>
 *
 * `code:` takes a machine id (hash.js machineIdOf), not a code: turning a
 * pasted code into its id needs the codec, which the app has and this module —
 * shipped to the website as it is — deliberately does not import.
 *
 * `accepts:`/`rejects:` run the word through every entry whose minimal DFA the
 * CI published — the one question here answered by running machines.
 */
export function parseLibraryQuery(text) {
  const q = { words: [], type: [], family: [], tag: [], author: [], badge: [], level: [], states: [], accepts: [], rejects: [], code: [] };
  const re = /(\w+):("([^"]*)"|\S+)|"([^"]*)"|(\S+)/g;
  let m;
  while ((m = re.exec(String(text || '')))) {
    if (m[1]) {
      const key = m[1].toLowerCase();
      const val = m[3] !== undefined ? m[3] : m[2];
      if (key === 'type' || key === 'machine') q.type.push(val.toLowerCase());
      else if (key === 'family') q.family.push(val.toLowerCase());
      else if (key === 'tag') q.tag.push(val.toLowerCase());
      else if (key === 'by' || key === 'author') q.author.push(val.toLowerCase().replace(/^@/, ''));
      else if (key === 'badge' || key === 'is') q.badge.push(val.toLowerCase());
      else if (key === 'level' || key === 'difficulty') q.level.push(val.toLowerCase());
      else if (key === 'states') { const c = parseComparison(val); if (c) q.states.push(c); }
      else if (key === 'accepts') q.accepts.push(val);
      else if (key === 'rejects') q.rejects.push(val);
      else if (key === 'code' && /^[0-9a-f]{16}$/i.test(val)) q.code.push(val.toLowerCase());
      else q.words.push(fold(m[0]));
    } else {
      q.words.push(fold(m[4] !== undefined ? m[4] : m[5]));
    }
  }
  q.words = q.words.filter(Boolean);
  return q;
}

function parseComparison(v) {
  const m = /^(<=|>=|<|>|=)?(\d+)$/.exec(v);
  if (!m) return null;
  return { op: m[1] || '=', n: Number(m[2]) };
}

function compare(x, { op, n }) {
  return op === '<' ? x < n : op === '<=' ? x <= n : op === '>' ? x > n : op === '>=' ? x >= n : x === n;
}

function fold(s) {
  return String(s || '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

function haystack(e) {
  return fold([e.title, e.blurb, e.machine, e.id, e.author.login, e.author.name, e.chapter, e.languageClass, e.standard || '', ...e.tags].join(' '));
}

/**
 * A raw word → symbols of Σ, longest match first, since a symbol may be
 * several characters. Whitespace separates tokens explicitly. `null` when some
 * part of the word is in no symbol at all — that word is not over Σ, so every
 * machine over Σ rejects it, and the caller says so rather than guessing.
 */
export function tokenizeOver(word, sigma) {
  const raw = String(word ?? '');
  if (raw === '' || raw === 'ε') return [];
  const syms = [...sigma].sort((a, b) => b.length - a.length);
  const out = [];
  for (const part of raw.split(/\s+/).filter(Boolean)) {
    let i = 0;
    while (i < part.length) {
      const s = syms.find(x => x && part.startsWith(x, i));
      if (!s) return null;
      out.push(s);
      i += s.length;
    }
  }
  return out;
}

/** Whether a published minimal DFA accepts `word`. `null` when the entry has no table. */
export function dfaAccepts(dfa, word) {
  if (!dfa) return null;
  const tokens = tokenizeOver(word, dfa.sigma);
  if (!tokens) return false;
  const k = dfa.sigma.length;
  const col = new Map(dfa.sigma.map((s, i) => [s, i]));
  const acc = new Set(dfa.acc);
  let q = dfa.start;
  for (const t of tokens) {
    q = dfa.delta[q * k + col.get(t)];
    if (q < 0 || q === undefined) return false;
  }
  return acc.has(q);
}

function matchesQuery(e, q) {
  if (q.type.length && !q.type.includes(e.machine.toLowerCase())) return false;
  if (q.family.length && !q.family.includes(e.category)) return false;
  if (q.tag.length && !q.tag.every(t => e.tags.includes(t))) return false;
  if (q.author.length && !q.author.includes(e.author.login.toLowerCase())) return false;
  if (q.badge.length && !q.badge.every(b => e.badges.some(x => x.id === b))) return false;
  if (q.level.length && !q.level.includes(e.difficulty)) return false;
  if (q.states.length && !q.states.every(c => compare(e.stats.states, c))) return false;
  if (q.code.length && !q.code.includes(e.machineId)) return false;
  if (q.accepts.length || q.rejects.length) {
    if (!e.dfa) return false;
    if (!q.accepts.every(w => dfaAccepts(e.dfa, w) === true)) return false;
    if (!q.rejects.every(w => dfaAccepts(e.dfa, w) === false)) return false;
  }
  return true;
}

function relevance(e, words) {
  if (!words.length) return 0;
  const hay = haystack(e);
  const title = fold(e.title);
  let score = 0;
  for (const w of words) {
    if (!hay.includes(w)) return -1;
    score += 1;
    if (title.includes(w)) score += 3;
    if (title.startsWith(w)) score += 2;
    if (e.tags.includes(w)) score += 2;
    if (fold(e.machine) === w) score += 2;
  }
  return score;
}

/**
 * Entries matching the query and the filters, sorted. `filters` carries the
 * sidebar's selections (`family`, `machine`, `badge`, `tag`, `level`) on top
 * of whatever the typed query says, so the two compose rather than one
 * overriding the other. `dir` reverses the field; an entry with no value for
 * it (an undated one) goes last either way, and ties fall to the title A–Z.
 */
export function queryLibrary(index, text = '', { sort = 'relevance', dir = null, filters = {} } = {}) {
  if (!index) return [];
  const q = typeof text === 'string' ? parseLibraryQuery(text) : text;
  const f = filters || {};
  if (f.family) q.family.push(f.family);
  if (f.machine) q.type.push(String(f.machine).toLowerCase());
  if (f.badge) q.badge.push(f.badge);
  if (f.tag) q.tag.push(String(f.tag).toLowerCase());
  if (f.level) q.level.push(f.level);
  if (f.author) q.author.push(String(f.author).toLowerCase());
  const scored = [];
  for (const e of index.entries) {
    if (!matchesQuery(e, q)) continue;
    const r = relevance(e, q.words);
    if (r < 0) continue;
    scored.push({ e, r });
  }
  const s = resolveSort(sort, dir);
  const title = (a, b) => a.e.title.localeCompare(b.e.title) || a.e.id.localeCompare(b.e.id);
  // Each field ascending, and '' / null where an entry has no value for it.
  const field = {
    added: x => dateOf(x.e.added),
    updated: x => dateOf(x.e.updated),
    states: x => x.e.stats.states,
    title: x => x.e.title
  }[s.key];
  if (!field) {
    // With no words, relevance is a tie everywhere, so it falls to the title.
    scored.sort((a, b) => b.r - a.r || title(a, b));
  } else {
    const sign = s.dir === 'desc' ? -1 : 1;
    scored.sort((a, b) => {
      const x = field(a), y = field(b);
      if (x === null || y === null) return (x === null) - (y === null) || title(a, b);
      const c = typeof x === 'number' ? x - y : x.localeCompare(y);
      return sign * c || (s.key === 'title' ? sign * a.e.id.localeCompare(b.e.id) : title(a, b));
    });
  }
  return scored.map(x => x.e);
}

/**
 * The newest `n` entries by `which` ('added' or 'updated'), for the home
 * pages' shelves. Recently updated holds only entries changed since they were
 * listed: every entry's last update is at least its listing, and a shelf that
 * repeated Recently added under another name would say nothing.
 */
export function recentEntries(index, which, n) {
  return queryLibrary(index, '', { sort: which, dir: 'desc' })
    .filter(e => dateOf(e[which]) !== null && (which !== 'updated' || wasUpdated(e)))
    .slice(0, n);
}

/**
 * The machine a home page opens on, drawn large with its names and labels:
 * `chosen` (library.config.json's `frontispiece`) when it names an entry, else
 * the index's own `frontispiece` (what the build chose), else a small labelled
 * machine from the featured collections: three or four states, a finite
 * automaton if there is one — the textbook's own figure — and of those the one
 * with the most edges (first listed on a tie). A figure a reader can take in
 * at a glance that still has something going on, which neither a busy
 * beaver's run nor a two-edge NFA is.
 *
 * `readable(e)` says the drawing will carry its labels, `drawable(e)` that
 * there is a drawing at all; the build answers from the drawings it made, the
 * app from the index's sketch.
 */
export function pickFrontispiece(index, { chosen = null, readable = () => true, drawable = () => true } = {}) {
  if (!index) return null;
  const byId = new Map(index.entries.map(e => [e.id, e]));
  const fixed = byId.get(chosen) || byId.get(index.frontispiece);
  if (fixed) return fixed;
  const featured = (index.featured || []).flatMap(id => index.collections.find(c => c.id === id)?.entries || []).map(id => byId.get(id)).filter(Boolean);
  const fits = e => e.stats.states >= 3 && e.stats.states <= 4 && drawable(e) && readable(e);
  const pool = featured.some(fits) ? featured : index.entries;
  const small = pool.filter(fits).sort((a, b) => (a.category !== 'fa') - (b.category !== 'fa') || b.stats.transitions - a.stats.transitions)[0];
  return small || pool.find(drawable) || null;
}

/** How many entries carry each facet value, for the filter chips. */
export function libraryFacets(entries) {
  const count = (map, k) => { if (k) map.set(k, (map.get(k) || 0) + 1); };
  const family = new Map(), machine = new Map(), badge = new Map(), tag = new Map(), level = new Map();
  for (const e of entries) {
    count(family, e.category);
    count(machine, e.machine);
    count(level, e.difficulty);
    e.badges.forEach(b => count(badge, b.id));
    e.tags.forEach(t => count(tag, t));
  }
  const sorted = m => [...m.entries()].sort((a, b) => b[1] - a[1] || String(a[0]).localeCompare(String(b[0])));
  return { family: sorted(family), machine: sorted(machine), badge: sorted(badge), tag: sorted(tag), level: sorted(level) };
}

/**
 * Other entries for the same machine (hash.js machineIdOf). Unlike a language
 * match this needs no confirming: the id is the hash of the machine's whole
 * canonical code, so agreeing on it is agreeing on the machine, short of a
 * 64-bit collision.
 */
export function sameMachineAs(index, machineId, exceptId = null) {
  if (!index || !machineId) return [];
  return index.entries.filter(e => e.machineId === machineId && e.id !== exceptId);
}

/** Other exercises setting the same task (analyze.js exerciseIdOf). */
export function sameTaskAs(index, taskId, exceptId = null) {
  if (!index || !taskId) return [];
  return index.entries.filter(e => e.taskId === taskId && e.id !== exceptId);
}

/** Other entries for the same language, found by fingerprint. The caller confirms exactly. */
export function sameLanguageAs(index, fingerprint, exceptId = null) {
  if (!index || !fingerprint) return [];
  return index.entries.filter(e => e.fingerprint === fingerprint && e.id !== exceptId);
}

/** The chain of entries this one was remixed from, nearest first, stopping at a cycle. */
export function remixAncestry(index, id) {
  const out = [];
  const seen = new Set([id]);
  let cur = entryById(index, id);
  while (cur && cur.forkOf && !seen.has(cur.forkOf)) {
    seen.add(cur.forkOf);
    const parent = entryById(index, cur.forkOf);
    if (!parent) break;
    out.push(parent);
    cur = parent;
  }
  return out;
}

/** A step count, short: 47,176,870 → 47.2M. */
export function shortCount(n) {
  if (!Number.isFinite(n)) return '0';
  if (n < 1000) return String(n);
  // Rounded first, then placed: 999,950 is "1M", not "1000k".
  const units = [[1e3, 'k'], [1e6, 'M'], [1e9, 'B']];
  for (const [size, unit] of units) {
    const digits = n < size * 10 ? (unit === 'M' ? 2 : 1) : n < size * 100 ? 1 : 0;
    const v = Number((n / size).toFixed(digits));
    if (v < 1000 || unit === 'B') return `${v}${unit}`;
  }
  return String(n);
}
